public class Bonus {
    public double salario;

    public Bonus(double salario) {
        this.salario = salario;
    }

    public double calcular() {
        double valor = salario * 1.5;
        if (valor > 10000.0) {
            throw new IllegalArgumentException("Limite excedido");
        }
        return valor;
    }

    public static void main(String[] args) {
        Bonus bonus = new Bonus(1000.0);
        System.out.println(bonus.calcular());
        try {
            new Bonus(20000.0).calcular();
            System.out.println("sem limite");
        } catch (IllegalArgumentException error) {
            System.out.println("limite ok");
        }
    }
}

